package xaero.map.server.mods.ftbteams;

import dev.ftb.mods.ftbteams.api.FTBTeamsAPI;
import dev.ftb.mods.ftbteams.api.Team;
import dev.ftb.mods.ftbteams.api.TeamRank;
import net.minecraft.world.entity.player.Player;
import xaero.map.server.radar.tracker.ISyncedPlayerTrackerSystem;

public class FTBTeamsSyncedPlayerTrackerSystem
implements ISyncedPlayerTrackerSystem {
    @Override
    public int getTrackingLevel(Player tracker, Player tracked) {
        if (FTBTeamsAPI.api().getManager().arePlayersInSameTeam(tracker.m_20148_(), tracked.m_20148_())) {
            return 2;
        }
        Team trackerTeam = FTBTeamsAPI.api().getManager().getTeamForPlayerID(tracker.m_20148_()).orElse(null);
        if (trackerTeam == null) {
            return 0;
        }
        Team trackedTeam = FTBTeamsAPI.api().getManager().getTeamForPlayerID(tracked.m_20148_()).orElse(null);
        if (trackedTeam == null) {
            return 0;
        }
        if (trackerTeam.getRankForPlayer(tracked.m_20148_()) == TeamRank.ALLY && trackedTeam.getRankForPlayer(tracker.m_20148_()) == TeamRank.ALLY) {
            return 1;
        }
        return 0;
    }

    @Override
    public boolean isPartySystem() {
        return true;
    }
}

