        private Builder() {
        }

        public Builder setDefault() {
            return this;
        }

        public ConfigOptionUITypeManager build() {
            return new ConfigOptionUITypeManager(new HashMap());
        }

        public static Builder begin() {
            return new Builder().setDefault();
        }
    }
}

